@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&family=Playfair+Display:ital,wght@0,600;0,700;1,600;1,700&display=swap');
:root{color-scheme:dark;--ink:#f4efe6;--muted:#9893a3;--gold:#e4bb72;--panel:#171720;--line:rgba(255,255,255,.09);--violet:#a887ff}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#0b0b10;color:var(--ink);font-family:Manrope,system-ui,sans-serif;overscroll-behavior:none}body{min-height:100dvh;background:radial-gradient(ellipse at 50% 30%,#22202d 0,#111118 56%,#0b0b10 100%);display:flex;justify-content:center;align-items:center;padding:clamp(10px,2.4vh,24px)}button{font:inherit;color:inherit}.game-shell{width:min(100%,520px);display:flex;flex-direction:column;gap:12px;user-select:none;-webkit-user-select:none}.topbar{height:48px;display:flex;align-items:center;justify-content:space-between;padding:0 3px}.brand{display:flex;align-items:center;gap:10px}.brand-mark{width:37px;height:37px;border:1px solid rgba(228,187,114,.36);border-radius:11px;display:grid;place-items:center;color:var(--gold);font-size:23px;background:linear-gradient(145deg,rgba(228,187,114,.13),rgba(228,187,114,.02));box-shadow:0 0 25px #e4bb7212}.eyebrow,.control-caption,.cooldown-note,.meter-label,.wave-card,.arena-tag,.bottom-note,.hint{font-family:'DM Mono',monospace;letter-spacing:.11em}.eyebrow{font-size:8px;color:#a6a0ad;display:block;margin-bottom:1px}.brand h1{font-size:18px;line-height:1;margin:0;font-weight:800;letter-spacing:.11em}.brand h1 span{color:var(--gold)}.icon-button{width:36px;height:36px;border:1px solid var(--line);border-radius:10px;background:#ffffff06;color:#d4cedc;font-size:16px;cursor:pointer}.icon-button:hover{background:#ffffff12}.status-row{display:grid;grid-template-columns:1fr 1fr auto;gap:8px}.meter-card,.wave-card{height:51px;border-radius:11px;border:1px solid var(--line);background:linear-gradient(145deg,#1d1c26,#15151c);padding:9px 11px}.meter-label{display:flex;justify-content:space-between;align-items:center;font-size:9px;color:#aaa5b1;letter-spacing:.08em}.meter-label strong{font-family:Manrope,sans-serif;color:#f4efe6;font-size:12px;letter-spacing:0}.meter{height:4px;margin-top:8px;border-radius:8px;background:#37333d;overflow:hidden}.meter i{height:100%;display:block;width:100%;background:linear-gradient(90deg,#ef777f,#ffab79);border-radius:8px;transition:width .18s}.mana-card .meter i{background:linear-gradient(90deg,#8b75f4,#71c7fb)}.wave-card{width:66px;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:1px;color:#a7a1b0;font-size:8px}.wave-card strong{font-family:Manrope,sans-serif;color:var(--gold);font-size:18px;letter-spacing:.05em}.arena-wrap{position:relative;width:100%;height:min(56dvh,590px);min-height:340px;overflow:hidden;border:1px solid rgba(230,209,171,.2);border-radius:17px;background:#15191a;box-shadow:0 18px 55px #0008,inset 0 0 45px #0005}canvas{display:block;width:100%;height:100%;touch-action:none}.arena-tag{position:absolute;top:12px;left:12px;right:12px;display:flex;align-items:center;gap:7px;pointer-events:none;color:#eee1c6;font-size:8px;text-shadow:0 1px 5px #000}.live-dot{width:6px;height:6px;border-radius:50%;background:#8ee4a7;box-shadow:0 0 8px #8ee4a7}.tag-divider{color:#777}.toast{position:absolute;left:50%;top:48px;transform:translate(-50%,-6px);opacity:0;white-space:nowrap;padding:7px 12px;border:1px solid #ffffff20;background:#111119dc;border-radius:20px;font-size:10px;color:#f2dfbd;transition:.22s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.overlay{position:absolute;inset:0;display:grid;place-items:center;background:linear-gradient(0deg,#0d0e15c9,#0d0e1599);backdrop-filter:blur(3px);transition:opacity .25s}.overlay.hidden{opacity:0;pointer-events:none}.overlay-card{width:min(84%,360px);padding:25px 22px 20px;text-align:center;border:1px solid #ffffff20;border-radius:16px;background:linear-gradient(145deg,#22212bdc,#15151ddf);box-shadow:0 20px 70px #0008}.crest{color:var(--gold);font-size:25px;margin-bottom:7px;text-shadow:0 0 22px #e4bb7277}.overlay-card .eyebrow{font-size:8px;color:var(--gold);margin:0 0 9px}.overlay-card h2{font-family:'Playfair Display',Georgia,serif;font-size:39px;line-height:.98;margin:0 0 13px;font-weight:600}.overlay-card h2 em{color:var(--gold)}.overlay-copy{max-width:280px;margin:0 auto 18px;color:#c2bdc9;font-size:12px;line-height:1.55}.primary-button{width:100%;height:43px;border:0;border-radius:9px;color:#221a10;font-weight:800;letter-spacing:.08em;font-size:10px;background:linear-gradient(100deg,#eacb8f,#d5a954);box-shadow:0 5px 22px #d4a5542c;cursor:pointer}.primary-button span{font-size:16px;margin-left:6px}.primary-button:active{transform:translateY(1px)}.hint{font-size:8px;color:#8f8998;margin:14px 0 0;letter-spacing:.06em}.hint b{color:#d8d0dc;font-weight:500}.controls{height:105px;display:grid;grid-template-columns:112px 1fr;gap:15px;align-items:center}.joystick-column{height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px}.control-caption{display:block;font-size:8px;color:#aaa4b2;letter-spacing:.14em}.joystick{width:78px;height:78px;touch-action:none}.joy-ring{position:relative;width:100%;height:100%;border:1px solid #ffffff1a;border-radius:50%;background:radial-gradient(circle,#282630aa,#17171e);box-shadow:inset 0 2px 8px #0007,0 4px 15px #0005}.joy-ring:before,.joy-ring:after{content:'';position:absolute;background:#ffffff0b}.joy-ring:before{width:1px;left:50%;top:10%;bottom:10%}.joy-ring:after{height:1px;top:50%;left:10%;right:10%}.joy-knob{position:absolute;left:50%;top:50%;width:31px;height:31px;border-radius:50%;transform:translate(-50%,-50%);border:1px solid #ffffff42;background:linear-gradient(145deg,#777382,#383642);box-shadow:0 4px 12px #0008,inset 0 1px #ffffff50;z-index:1}.spell-column{min-width:0}.spell-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:7px;padding:0 1px}.cooldown-note{font-size:7px;color:#777382;letter-spacing:.1em}.spell-list{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.spell-button{height:61px;position:relative;display:grid;grid-template-columns:28px 1fr;grid-template-rows:1fr 1fr;align-items:center;text-align:left;padding:8px 7px;border-radius:11px;border:1px solid var(--line);background:linear-gradient(145deg,#1c1b24,#14141b);cursor:pointer;transition:transform .12s,border-color .15s,background .15s;touch-action:manipulation}.spell-button:active{transform:scale(.97)}.spell-button.selected{border-color:#e4bb726e;background:linear-gradient(145deg,#30291f,#1c1a20);box-shadow:0 0 15px #d6aa5420}.spell-icon{grid-row:1/3;width:24px;height:24px;display:grid;place-items:center;border-radius:8px;font-size:15px}.spell-icon.fire{color:#ffad75;background:#f56d281c}.spell-icon.ice{color:#87d9ff;background:#4da9eb20}.spell-icon.void{color:#c4a0ff;background:#a06aff20}.spell-name{font-size:9px;font-weight:700;white-space:nowrap}.spell-key{position:absolute;top:5px;right:6px;color:#746e7c;font:8px 'DM Mono',monospace}.bottom-note{display:flex;justify-content:space-between;align-items:center;color:#6e6977;font-size:8px;letter-spacing:.09em;padding:0 4px}.bottom-note span:nth-child(2){color:#9e8d70}.bottom-note button{border:0;background:transparent;color:#90899a;font-size:15px;width:25px;height:21px;cursor:pointer}button:focus-visible,canvas:focus-visible{outline:2px solid #e4bb72;outline-offset:2px}
@media(max-height:700px){body{padding:8px}.game-shell{gap:8px}.arena-wrap{height:min(49dvh,480px);min-height:280px}.controls{height:91px}.joystick{width:68px;height:68px}.spell-button{height:54px}.status-row .meter-card,.wave-card{height:46px}.meter{margin-top:6px}}@media(max-width:390px){.game-shell{gap:8px}.arena-wrap{min-height:320px;height:49dvh}.controls{grid-template-columns:92px 1fr;gap:8px}.spell-list{gap:5px}.spell-button{padding:7px 5px;grid-template-columns:24px 1fr}.spell-name{font-size:8px}.spell-icon{width:21px;height:21px}.bottom-note{font-size:7px}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const $ = id => document.getElementById(id);
  const ui = { hp: $('hpText'), hpMeter: $('hpMeter'), mana: $('manaText'), manaMeter: $('manaMeter'), wave: $('waveText'), enemyCount: $('enemyCount'), overlay: $('overlay'), eyebrow: $('overlayEyebrow'), title: $('overlayTitle'), copy: $('overlayCopy'), action: $('overlayAction'), hint: $('overlayHint'), toast: $('toast'), arena: $('arenaName'), score: $('scoreText'), joy: $('joystick'), knob: $('joyKnob') };
  const spells = {
    fire: { name: 'Fireball', cost: 18, cooldown: .48, damage: 29, speed: 330, color: '#ff9258', radius: 5, splash: 45 },
    ice: { name: 'Ice Dart', cost: 13, cooldown: .30, damage: 18, speed: 430, color: '#81dfff', radius: 4, slow: 2.4 },
    void: { name: 'Void Orb', cost: 30, cooldown: .82, damage: 48, speed: 245, color: '#bd8cff', radius: 8, splash: 24 }
  };
  const arenas = ['CATHEDRAL REVIVAL', 'THE SUNKEN CHAPEL', 'ASHEN SANCTUM', 'MOONLIT CLOISTER'];
  let W = 0, H = 0, dpr = 1, last = 0, state = 'intro', selected = 'fire', wave = 1, score = 0;
  let player, enemies = [], shots = [], particles = [], decor = [], keys = {}, move = { x: 0, y: 0 }, joyPointer = null, pointer = null;
  let castCooldown = 0, spawnClock = 0, waveWait = 0, toastTimer = 0, soundOn = false, audio = null, shake = 0, frame = 0;
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const rand = (a, b) => a + Math.random() * (b - a);
  const dist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);
  function resize() {
